<?php require ROOT.'/app/Views/admin/nav.php'; ?><div class="page-heading"><h1><?= e($title) ?></h1><p>A análise desta fila não muda automaticamente a situação do relato. Abra a ocorrência para moderá-la.</p></div>
<?php if (!$rows): ?><div class="empty-state"><h2>Nenhuma solicitação</h2><p>As novas solicitações da comunidade aparecerão aqui.</p></div><?php endif ?>
<?php foreach ($rows as $r): ?><section class="surface mb-3"><h2 class="h5"><a href="<?= e(url('/ocorrencia',['id'=>$r['ocorrencia_id']])) ?>"><?= e($r['titulo']) ?></a></h2><p><?= e($r['motivo']??'Sugestão de resolução') ?> · <?= e($r['status']) ?></p><p><?= e($r['descricao']) ?></p><?php if ($r['status']==='PENDENTE'): ?><form class="form-stack" action="<?= e(url('/admin/solicitacoes')) ?>" method="post"><?= csrf() ?><input type="hidden" name="tipo" value="<?= e($type) ?>"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><label for="parecer-<?= (int)$r['id'] ?>">Parecer</label><textarea class="form-control" id="parecer-<?= (int)$r['id'] ?>" name="parecer" minlength="5" maxlength="2000" required></textarea><div class="d-flex gap-3"><button class="btn btn-primary" name="status" value="RESOLVIDA">Concluir análise</button><button class="btn btn-outline-secondary" name="status" value="ARQUIVADA">Arquivar solicitação</button></div></form><?php else: ?><p><strong>Parecer:</strong> <?= e($r['parecer']) ?></p><?php endif ?></section><?php endforeach ?>
